// did not say which.
func filterGrant(f *levyan.GrantFilter) (predicate.Grant, error) {
	ps := make([]predicate.Grant, 0, 1)
	if f.HasRef() {
		p, err := bare.GrantPick(f.GetRef())
		if err != nil {
			return nil, err
		}

		ps = append(ps, p)
	}
	if f.HasWorkspace() {
		w := f.GetWorkspace()
		if b := w.GetId(); len(b) > 0 {
			// The **foreign key column** on this row, which is what an
			// edge is. A subquery for a comparison against an indexed
			// column is work nobody asked for.
			k, err := entuuid.FromBytes(b)
			if err != nil {
				return nil, status.Errorf(codes.InvalidArgument, "workspace: %s", err)
			}

			ps = append(ps, entGrant.WorkspaceIdEQ(k))
		} else {
			// Named some other way -- an alias, a slug. Resolving it
			// would be a read, and a predicate is built without one, so
			// it becomes a condition on the target instead. One hop,
			// against whatever index that column has.
			q, err := bare.WorkspacePick(w)
			if err != nil {
				return nil, err
			}

			ps = append(ps, entGrant.HasWorkspaceWith(q))
		}
	}
	if len(ps) == 0 {
		return nil, status.Error(codes.InvalidArgument, "a filter that names nothing")
	}

	return entGrant.And(ps...), nil
}

type sinkHolder struct {
	levyan.HolderServiceServer
	store  bare.Store
	w      *watch.Watch
	namer  slug.Namer
	joined bool
}

func (s Sink) Holder() levyan.HolderServiceServer {
	v := sinkHolder{s.Server.Holder(), s.Server.Store, s.w, s.namer, s.joined}
	v.HolderServiceServer = bare.HolderWithAddRule(v.HolderServiceServer, v.admit)
	return v
}

// admit decides the name of a row an Add of Holder writes, refusing one
// that was given and cannot be one.
//
// It is asked of an Add and of every item of an AddMany; see [Sink.Holder].
//
// The name goes through [Sink.WithNamer], which is unset in most
// deployments and then means: fold what was given, and make a name up
// when nothing was -- for the reason `bare.Minter` makes a key up. An app
// whose rows have to be named says so with `slug.Required`; see
// `slug.Names` for why that is the way round it is.
func (s sinkHolder) admit(ctx context.Context, req *levyan.HolderAddRequest) (*levyan.HolderAddRequest, error) {
	// Copied rather than written to: the request belongs to whoever called,
	// and for a call made in this process that is a message they may still
	// be holding -- a server that changed a caller's own field would be
	// changing a value they can read back.
	r := proto.CloneOf(req)

	v, err := slug.NameWith(ctx, s.namer, "levyan.Holder", req.GetAlias(), req)
	if err != nil {
		return nil, pderr.At("alias", err)
	}
	r.SetAlias(v)

	return r, nil
}

// Add tries again when the name it made up was taken.
//
// The name is [sinkHolder.admit]'s, and every try goes through it, so a
// name made up is made up again and a name given is the same each time.
func (s sinkHolder) Add(ctx context.Context, req *levyan.HolderAddRequest) (*levyan.Holder, error) {
	// How many names to try. More than one only when the caller named
	// nothing -- then the name is this server's and a collision is this
	// server's to resolve. A name the caller gave is theirs, and quietly
	// choosing a different one would write a row they did not ask for.
	//
	// And only when this Add opens its own transaction; see [Sink.joined].
	tries := 1
	if req.GetAlias() == "" && !s.joined {
		tries = slug.Tries
	}

	for try := 0; ; try++ {
		res, err := s.HolderServiceServer.Add(ctx, req)
		if err == nil || try+1 >= tries || status.Code(err) != codes.AlreadyExists {
			// Whatever it was, said in the words it was said in. Rewriting
			// it into "no free name" would assert the one thing this cannot
			// know -- a duplicate key is the same code -- and would say it
			// loudest exactly when it is wrong.
			return res, err
		}
	}
}

// Patch folds a name it was given, and says nothing about one it was not.
//
// The presence is the whole of the difference from [sinkHolder.Add]: a patch
// that does not mention the alias is not a patch setting it to the empty
// string, and refusing one would make every patch of any other field carry
// the name along.
//
// The namer is **not** asked here, and that is the second difference. It
// decides the name of a row being made; a patch that cleared the alias is
// a caller asking for something invalid, and answering that with an
// invented name would hand them a row they did not ask for.
//
// And it forgets what the transaction was told about the row; see
// [sinkHolder.Apply].
func (s sinkHolder) Patch(ctx context.Context, req *levyan.HolderPatchRequest) (*levyan.Holder, error) {
	seen.Forget(s.store.Db.Driver(), "Holder", req.GetRef())

	if !req.HasAlias() {
		return s.HolderServiceServer.Patch(ctx, req)
	}

	v, err := slug.ParseAlias(req.GetAlias())
	if err != nil {
		return nil, pderr.At("alias", err)
	}

	req = proto.CloneOf(req)
	req.SetAlias(v)

	return s.HolderServiceServer.Patch(ctx, req)
}

// Erase forgets what the transaction was told about the row, before it is
// erased: whether a frame may see it, and where a walk from it arrives.
// Neither is true of a row that is gone, nor of another put under its
// key. See [seen.Forget].
func (s sinkHolder) Erase(ctx context.Context, req *levyan.HolderRef) (*levyan.HolderEraseResponse, error) {
	seen.Forget(s.store.Db.Driver(), "Holder", req)

	return s.HolderServiceServer.Erase(ctx, req)
}

// Apply forgets what the transaction was told about the row, before it is
// written: a document may move it to a set the caller cannot see. See
// [seen.Forget].
func (s sinkHolder) Apply(ctx context.Context, req *levyan.HolderApplyRequest) (*levyan.Holder, error) {
	seen.Forget(s.store.Db.Driver(), "Holder", req.GetRef())

	return s.HolderServiceServer.Apply(ctx, req)
}

// orderHolder is how Holders come back.
//
// The last column is the key, and it is not decoration: a cursor cannot
// tell apart two rows equal in every column of the order, so the page after
// the first of them either repeats the second or skips it. Rows written by
// one request are stamped a moment apart at best.
var orderHolder = []sqlpage.Order{
	{Column: entHolder.FieldDateCreated, Desc: false},
	{Column: entHolder.FieldId, Desc: false},
}

func afterHolder(v string, by []sqlpage.Order, tag string) (func(*sql.Selector), error) {
	var (
		at0 time.Time
		at1 uuid.UUID
	)
	if err := pdAfter(v, tag, &at0, &at1); err != nil {
		return nil, err
	}

	return sqlpage.After(by, []any{at0, at1})
}

func nextHolder(last *ent.Holder, tag string) (string, error) {
	return pdNext(tag, last.DateCreated, last.Id)
}

// orderByHolder is an order as ent orders a query by it.
func orderByHolder(by []sqlpage.Order) []entHolder.OrderOption {
	out := make([]entHolder.OrderOption, len(by))
	for i, o := range by {
		if o.Desc {
			out[i] = sql.OrderByField(o.Column, sql.OrderDesc()).ToFunc()
			continue
		}

		out[i] = sql.OrderByField(o.Column).ToFunc()
	}

	return out
}

const (
	// HolderPageSize is what a request that did not say gets, and
	// HolderPageLimit is the most it gets however loudly it asks.
	HolderPageSize  = 20
	HolderPageLimit = 100

	// HolderFilterLimit is how many filters one request may carry. Each is a
	// predicate in the same query, so it is what says how much of the
	// database a request may ask to read -- and it is refused rather than
	// clamped, because dropping half the filters would answer a question
	// nobody asked.
	HolderFilterLimit = 32
)

// List answers with the Holders that match any of the given filters, or with
// every one there is if the request named none, a page at a time.
func (s sinkHolder) List(ctx context.Context, req *levyan.HolderListRequest) (*levyan.HolderListResponse, error) {
	q := s.store.Db.Holder.Query()

	// Through the same narrowing every generated read goes through, and not
	// by asking the scope alone: what narrows a read is the wall today and
	// the wall and something else tomorrow, and a list that reached past it
	// would be the one read that missed the something else.
	if p, err := bare.HolderNarrow(ctx, s.store.Scope, nil); err != nil {
		return nil, err
	} else if p != nil {
		q.Where(p)
	}

	if fs := req.GetFilters(); len(fs) > 0 {
		if len(fs) > HolderFilterLimit {
			return nil, status.Errorf(codes.InvalidArgument,
				"filters: %d of them, and %d is the most one list carries", len(fs), HolderFilterLimit)
		}

		ps := make([]predicate.Holder, 0, len(fs))
		for i, f := range fs {
			p, err := filterHolder(f)
			if err != nil {
				return nil, status.Errorf(codes.InvalidArgument, "filters[%d]: %s", i, err)
			}

			ps = append(ps, p)
		}

		q.Where(entHolder.Or(ps...))
	}

	// Which order, and which way: one the schema declared, and never one a
	// request makes up, since an order is a walk of an index.
	by, after, next, tag := orderHolder, afterHolder, nextHolder, ""
	if req.GetReverse() {
		// The same index, walked from the other end.
		by, tag = pdReverse(by), tag+"/reverse"
	}

	if v := req.GetAfter(); v != "" {
		p, err := after(v, by, tag)
		if err != nil {
			return nil, status.Errorf(codes.InvalidArgument, "after: %s", err)
		}

		q.Where(p)
	}

	// One row more than the page, which is how "is there another" is answered
	// without a second query and without a count. The extra is dropped before
	// the answer is built; it was only ever asked for to see whether it was
	// there -- so a full last page answers with no cursor rather than sending
	// the caller back for an empty one.
	size := sqlpage.Size(int(req.GetSize()), HolderPageSize, HolderPageLimit)
	us, err := q.Order(orderByHolder(by)...).Limit(size + 1).All(ctx)
	if err != nil {
		return nil, err
	}

	more := len(us) > size
	if more {
		us = us[:size]
	}

	items := make([]*levyan.Holder, len(us))
	for i, u := range us {
		items[i] = u.Proto()
	}

	res := levyan.HolderListResponse_builder{Items: items}.Build()
	if more {
		v, err := next(us[len(us)-1], tag)
		if err != nil {
			return nil, status.Errorf(codes.Internal, "next: %s", err)
		}

		res.SetNext(v)
	}

	return res, nil
}

// filterHolder turns one filter into the predicate that selects what it
// names. Naming nothing is refused, since the request asked for "these" and
// did not say which.
func filterHolder(f *levyan.HolderFilter) (predicate.Holder, error) {
	ps := make([]predicate.Holder, 0, 1)
	if f.HasRef() {
		p, err := bare.HolderPick(f.GetRef())
		if err != nil {
			return nil, err
		}

		ps = append(ps, p)
	}
	if f.HasTenant() {
		w := f.GetTenant()
		if b := w.GetId(); len(b) > 0 {
			// The **foreign key column** on this row, which is what an
			// edge is. A subquery for a comparison against an indexed
			// column is work nobody asked for.
			k, err := entuuid.FromBytes(b)
			if err != nil {
				return nil, status.Errorf(codes.InvalidArgument, "tenant: %s", err)
			}

			ps = append(ps, entHolder.TenantIdEQ(k))
		} else {
			// Named some other way -- an alias, a slug. Resolving it
			// would be a read, and a predicate is built without one, so
			// it becomes a condition on the target instead. One hop,
			// against whatever index that column has.
			q, err := bare.TenantPick(w)
			if err != nil {
				return nil, err
			}

			ps = append(ps, entHolder.HasTenantWith(q))
		}
	}
	if m := f.GetLabels(); len(m) > 0 {
		ks := make([]string, 0, len(m))
		for k := range m {
			ks = append(ks, k)
		}
		sort.Strings(ks)

		for _, k := range ks {
			ps = append(ps, predicate.Holder(func(s *sql.Selector) {
				s.Where(sql.And(
					sqljson.HasKey(entHolder.FieldLabels, sqljson.Path(k)),
					sqljson.ValueEQ(entHolder.FieldLabels, m[k], sqljson.Path(k)),
				))
			}))
		}
	}
	if len(ps) == 0 {
		return nil, status.Error(codes.InvalidArgument, "a filter that names nothing")
	}

	return entHolder.And(ps...), nil
}

// HolderService is the prefix of every Rpc of that service, which is how a
// change is known to be about a Holder. A service is named for the entity it
// is about, so the name carries it.
var HolderService = watch.ServiceOf(levyan.HolderService_Get_FullMethodName)

// Watch answers with the Holders this caller may see, as they are now and as
// they change.
//
// What is sent is **state and never a delta**, which is what makes a stream
// that missed something still correct: the next item about a row carries the
// whole of it, so a client converges rather than replays. It is also what
// makes the first message safe to duplicate against the ones after it.
func (s sinkHolder) Watch(req *levyan.HolderWatchRequest, out grpc.ServerStreamingServer[levyan.HolderWatchResponse]) error {
	ctx := out.Context()

	// A watch with no filters is the whole table, forever. It is the one
	// shape that has no cap at all, so it is the one shape refused.
	fs := req.GetFilters()
	switch {
	case len(fs) == 0:
		return status.Error(codes.InvalidArgument,
			"filters: a watch says which rows it is about; one that says nothing is the whole table, for as long as it is open")
	case len(fs) > HolderFilterLimit:
		return status.Errorf(codes.InvalidArgument,
			"filters: %d of them, and %d is the most one watch carries", len(fs), HolderFilterLimit)
	}

	// Resolved before anything is subscribed to, so a name that names
	// nothing is an answer rather than a stream that quietly watches none.
	watching, err := s.watchHolderKeys(ctx, fs)
	if err != nil {
		return err
	}

	var snapshot func(watch.Seen) error
	if !req.GetSkipSnapshot() {
		snapshot = func(sent watch.Seen) error { return s.watchNow(ctx, req, out, sent) }
	}

	if s.w == nil {
		return status.Error(codes.Unimplemented,
			"this deployment publishes no changes; see WithWatch")
	}

	return watch.Stream(ctx, s.w, HolderService, snapshot,
		func(ks map[pdid.Id]string, sent watch.Seen) error {
			items := make([]*levyan.HolderWatchItem, 0, len(ks))
			for k, action := range ks {
				u, err := s.watchRead(ctx, watching, k)
				if err != nil {
					return err
				}
				if u == nil && !sent[k] {
					// Not theirs, or not what they asked for, and they
					// have never been told about it. A row that never
					// matched is not news.
					continue
				}

				sent[k] = u != nil
				items = append(items, levyan.HolderWatchItem_builder{
					Id:     k.Bytes(),
					Value:  u,
					Action: action,
				}.Build())
			}
			if len(items) == 0 {
				return nil
			}

			return out.Send(levyan.HolderWatchResponse_builder{Items: items}.Build())
		})
}

// watchNow sends what matches right now, through the same List a caller
// would have called -- so what a stream begins with and what a list answers
// cannot disagree, and a client does not have to do both and race them.
func (s sinkHolder) watchNow(
	ctx context.Context, req *levyan.HolderWatchRequest, out grpc.ServerStreamingServer[levyan.HolderWatchResponse],
	sent watch.Seen,
) error {
	after := ""
	for {
		res, err := s.List(ctx, levyan.HolderListRequest_builder{
			Filters: req.GetFilters(),
			After:   after,
		}.Build())
		if err != nil {
			return err
		}

		items := make([]*levyan.HolderWatchItem, 0, len(res.GetItems()))
		for _, u := range res.GetItems() {
			k, err := pdid.From(u.GetId())
			if err != nil {
				return err
			}

			sent[k] = true
			// No action: this is not something anybody asked for, it is
			// what is already there.
			items = append(items, levyan.HolderWatchItem_builder{Id: u.GetId(), Value: u}.Build())
		}
		if len(items) > 0 {
			if err := out.Send(levyan.HolderWatchResponse_builder{Items: items}.Build()); err != nil {
				return err
			}
		}

		if after = res.GetNext(); after == "" {
			return nil
		}
	}
}

// watchRead answers with the row as it is now, or nil when it is no longer
// one this caller may see -- erased, walled off, or no longer matching what
// they asked for. The three are deliberately indistinguishable to a caller:
// a stream that told them apart would be saying which rows stopped being
// theirs, which is the thing the wall is for.
//
// The Get is what keeps the wall out of this file. It goes through the same
// server every other read does, with the context of the caller who asked, so
// a row they may not see comes back NotFound and is never sent.
func (s sinkHolder) watchRead(
	ctx context.Context, watching []pdid.Id, k pdid.Id,
) (*levyan.Holder, error) {
	// Not one of the rows this stream is about. Asked before the read, so a
	// busy table costs a stream nothing for the rows it does not watch.
	if !slices.Contains(watching, k) {
		return nil, nil
	}

	v, err := s.Get(ctx, levyan.HolderGetRequest_builder{
		Ref: levyan.HolderRef_builder{Id: k.Bytes()}.Build(),
	}.Build())
	if err != nil {
		if status.Code(err) == codes.NotFound {
			return nil, nil
		}

		return nil, err
	}

	return v, nil
}

// watchHolderKeys is the rows a stream is about, resolved once when it opens.
//
// A filter names a row and a row is named several ways -- by identifier, or
// by whatever unique index the schema declared. Resolving them here rather
// than comparing them per event does three things: the comparison afterwards
// is an identifier against an identifier, a name that names nothing is
// refused when the stream opens rather than silently watching nothing, and a
// row renamed while the stream is open goes on being the row that was asked
// for -- which is what somebody watching a thing meant.
func (s sinkHolder) watchHolderKeys(
	ctx context.Context, fs []*levyan.HolderFilter,
) ([]pdid.Id, error) {
	ks := make([]pdid.Id, 0, len(fs))
	for i, f := range fs {
		if !f.HasRef() {
			return nil, status.Errorf(codes.InvalidArgument,
				"filters[%d]: a watch says which rows it is about by naming them", i)
		}

		v, err := s.Get(ctx, levyan.HolderGetRequest_builder{Ref: f.GetRef()}.Build())
		if err != nil {
			return nil, err
		}

		k, err := pdid.From(v.GetId())
		if err != nil {
			return nil, err
		}

		ks = append(ks, k)
	}

	return ks, nil
}

type sinkLink struct {
	levyan.LinkServiceServer
	store  bare.Store
	w      *watch.Watch
	namer  slug.Namer
	joined bool
}

func (s Sink) Link() levyan.LinkServiceServer {
	v := sinkLink{s.Server.Link(), s.Server.Store, s.w, s.namer, s.joined}
	v.LinkServiceServer = bare.LinkWithAddRule(v.LinkServiceServer, v.admit)
	return v
}

// admit is what is said of the tenancy of a row an Add of Link writes: it
// refuses it when its paths to a tenant do not agree.
//
// It is asked of an Add and of every item of an AddMany; see [Sink.Link].
func (s sinkLink) admit(ctx context.Context, req *levyan.LinkAddRequest) (*levyan.LinkAddRequest, error) {
	// Copied rather than written to: the request belongs to whoever called,
	// and for a call made in this process that is a message they may still
	// be holding -- a server that changed a caller's own field would be
	// changing a value they can read back.
	r := proto.CloneOf(req)

	if err := s.tenancy(ctx, r); err != nil {
		return nil, err
	}

	return r, nil
}

// Apply forgets what the transaction was told about the row, before it is
// written: a document may move it to a set the caller cannot see. See
// [seen.Forget].
func (s sinkLink) Apply(ctx context.Context, req *levyan.LinkApplyRequest) (*levyan.Link, error) {
	seen.Forget(s.store.Db.Driver(), "Link", req.GetRef())

	return s.LinkServiceServer.Apply(ctx, req)
}

// Patch forgets what the transaction was told about the row, before it is
// written; see [sinkLink.Apply].
func (s sinkLink) Patch(ctx context.Context, req *levyan.LinkPatchRequest) (*levyan.Link, error) {
	seen.Forget(s.store.Db.Driver(), "Link", req.GetRef())

	return s.LinkServiceServer.Patch(ctx, req)
}

// tenantAtTenant is the tenant "tenant" arrives at.
func (s sinkLink) tenantAtTenant(ctx context.Context, ref *levyan.TenantRef) ([]byte, error) {
	if ref == nil {
		return nil, pderr.Invalidf("tenant", "required: it is what says which tenant this belongs to")
	}

	// Asked once a transaction: no step past the first can be repointed, so
	// where this walk arrives from a row is decided until the row is
	// written. See [seen.Tenant].
	return seen.Tenant(s.store.Db.Driver(), "Tenant", "", ref, func() ([]byte, error) {
		// The row the edge names, picked the way every other reference is.
		pick, err := bare.TenantPick(ref)
		if err != nil {
			return nil, pderr.At("tenant", err)
		}

		k, err := s.store.Db.Tenant.Query().Where(pick).OnlyId(ctx)
		if err != nil {
			// Not there, or more than one -- both are the reference being wrong,
			// and both are the caller's to fix.
			return nil, pderr.Invalidf("tenant", "it does not name one row")
		}

		return k[:], nil
	})
}

// tenantAtWorkspaceTenant is the tenant "workspace.tenant" arrives at.
func (s sinkLink) tenantAtWorkspaceTenant(ctx context.Context, ref *levyan.WorkspaceRef) ([]byte, error) {
	if ref == nil {
		return nil, pderr.Invalidf("workspace", "required: it is what says which tenant this belongs to")
	}

	// Asked once a transaction: no step past the first can be repointed, so
	// where this walk arrives from a row is decided until the row is
	// written. See [seen.Tenant].
	return seen.Tenant(s.store.Db.Driver(), "Workspace", "tenant", ref, func() ([]byte, error) {
		// The row the edge names, picked the way every other reference is.
		pick, err := bare.WorkspacePick(ref)
		if err != nil {
			return nil, pderr.At("workspace", err)
		}

		k, err := s.store.Db.Workspace.Query().Where(pick).QueryTenant().OnlyId(ctx)
		if err != nil {
			// Not there, or more than one -- both are the reference being wrong,
			// and both are the caller's to fix.
			return nil, pderr.Invalidf("workspace", "it does not name one row")
		}

		return k[:], nil
	})
}

// tenantAtOfferTenant is the tenant "offer.tenant" arrives at.
func (s sinkLink) tenantAtOfferTenant(ctx context.Context, ref *levyan.OfferRef) ([]byte, error) {
	if ref == nil {
		return nil, pderr.Invalidf("offer", "required: it is what says which tenant this belongs to")
	}

	// Asked once a transaction: no step past the first can be repointed, so
	// where this walk arrives from a row is decided until the row is
	// written. See [seen.Tenant].
	return seen.Tenant(s.store.Db.Driver(), "Offer", "tenant", ref, func() ([]byte, error) {
		// The row the edge names, picked the way every other reference is.
		pick, err := bare.OfferPick(ref)
		if err != nil {
			return nil, pderr.At("offer", err)
		}

		k, err := s.store.Db.Offer.Query().Where(pick).QueryTenant().OnlyId(ctx)
		if err != nil {
			// Not there, or more than one -- both are the reference being wrong,
			// and both are the caller's to fix.
			return nil, pderr.Invalidf("offer", "it does not name one row")
		}

		return k[:], nil
	})
}

// tenancy fills what the schema says this row's tenant is, and refuses a
// row whose other paths do not agree with it.
//
// The request is already this server's copy by the time it arrives, so it
// is written to rather than cloned again.
func (s sinkLink) tenancy(ctx context.Context, req *levyan.LinkAddRequest) error {
	want, err := s.tenantAtTenant(ctx, req.GetTenant())
	if err != nil {
		return err
	}

	if req.HasWorkspace() {
		got, err := s.tenantAtWorkspaceTenant(ctx, req.GetWorkspace())
		if err != nil {
			return err
		}
		if string(got) != string(want) {
			// Both exist and both are visible to whoever is writing --
			// the gate already saw to that. What it cannot see is that
			// they are in different tenants, because it asks "may I read
			// this" and a caller who holds several tenants may read both.
			return pderr.Invalidf("workspace",
				"it is in another tenant than tenant")
		}
	}

	if req.HasOffer() {
		got, err := s.tenantAtOfferTenant(ctx, req.GetOffer())
		if err != nil {
			return err
		}
		if string(got) != string(want) {
			// Both exist and both are visible to whoever is writing --
			// the gate already saw to that. What it cannot see is that
			// they are in different tenants, because it asks "may I read
			// this" and a caller who holds several tenants may read both.
			return pderr.Invalidf("offer",
				"it is in another tenant than tenant")
		}
	}

	return nil
}

