// snapshot runs `fn` on one read-only transaction, so that a page of rows and
// the trail about them are read at one moment of the database: REPEATABLE
// READ on PostgreSQL, and what every SQLite transaction already is.
func snapshot(ctx context.Context, db *ent.Client, fn func(context.Context, *ent.Client) error) error {
	opts := &sql1.TxOptions{ReadOnly: true}
	if db.Dialect() == dialect.Postgres {
		opts.Isolation = sql1.LevelRepeatableRead
	}

	tx, err := db.BeginTx(ctx, opts)
	if err != nil {
		return err
	}
	defer tx.Rollback()

	return fn(ctx, tx.Client())
}

// objects is what `rows` are about.
func objects(rows []audit.Live) []pdid.Id {
	out := make([]pdid.Id, len(rows))
	for i, v := range rows {
		out[i] = v.Object
	}

	return out
}

// newestDigests is what the newest line of the trail in the database about
// each of `ids` keeps of its digest, and the line itself: the lines about
// them read newest first, and the first of each thing's kept.
func newestDigests(ctx context.Context, db *ent.Client, ids []pdid.Id) (map[pdid.Id]audit.Recorded, error) {
	out := map[pdid.Id]audit.Recorded{}
	if len(ids) == 0 {
		return out, nil
	}

	vs, err := db.Audit.Query().
		Where(entAudit.ObjectIdIn(uuids(ids)...)).
		Order(entAudit.ByDateCreated(sql.OrderDesc()), entAudit.ById(sql.OrderDesc())).
		Select(entAudit.FieldId, entAudit.FieldDateCreated, entAudit.FieldAction, entAudit.FieldObjectId, entAudit.FieldDigest, entAudit.FieldDigestFields).
		All(ctx)
	if err != nil {
		return nil, err
	}

	for _, v := range vs {
		k := pdid.Id(v.ObjectId)
		if _, ok := out[k]; !ok {
			out[k] = audit.Recorded{
				Digest: v.Digest,
				Fields: v.DigestFields,
				Line:   audit.Line{Id: v.Id, Created: v.DateCreated, Action: v.Action},
			}
		}
	}

	return out, nil
}

// goneOf is, of `ids`, the ones `rows` -- the ones of them that are rows --
// does not have, each with the newest line of the trail in the database
// about it, and nil for one the database's trail says nothing about.
func goneOf(ctx context.Context, db *ent.Client, ids []pdid.Id, rows []audit.Live) (map[pdid.Id]*audit.Recorded, error) {
	there := map[pdid.Id]bool{}
	for _, v := range rows {
		there[v.Object] = true
	}

	absent := []pdid.Id{}
	for _, id := range ids {
		if !there[id] {
			absent = append(absent, id)
		}
	}

	lines, err := newestDigests(ctx, db, absent)
	if err != nil {
		return nil, err
	}

	out := make(map[pdid.Id]*audit.Recorded, len(absent))
	for _, id := range absent {
		if r, ok := lines[id]; ok {
			out[id] = &r
		} else {
			out[id] = nil
		}
	}

	return out, nil
}

// trailObjects hands `yield` the things of kind `d` the database's trail is
// about, a page of its lines at a time, oldest first -- by the index on
// `(domain, date_created)`, which a DISTINCT over the table would not use,
// and each page from where the one before ended rather than from the kind's
// first line. A thing with more than one line is handed more than once.
func trailObjects(ctx context.Context, db *ent.Client, d pdid.Domain, yield func([]pdid.Id) error) error {
	var after *ent.Audit
	for {
		q := db.Audit.Query().Where(entAudit.DomainEQ(uint32(d)))
		if after != nil {
			// After the cursor, as one comparison of the pair: an index starts the read
			// at it, where the OR it means is a filter and every page is read from the
			// first row.
			q = q.Where(func(s *sql.Selector) {
				s.Where(sql.CompositeGT([]string{s.C(entAudit.FieldDateCreated), s.C(entAudit.FieldId)}, after.DateCreated, after.Id))
			})
		}

		vs, err := q.
			Order(entAudit.ByDateCreated(), entAudit.ById()).
			Select(entAudit.FieldId, entAudit.FieldDateCreated, entAudit.FieldObjectId).
			Limit(audit.RowsPage).
			All(ctx)
		if err != nil {
			return err
		}
		if len(vs) == 0 {
			return nil
		}

		ids := make([]pdid.Id, len(vs))
		for i, v := range vs {
			ids[i] = pdid.Id(v.ObjectId)
		}
		if err := yield(ids); err != nil {
			return err
		}
		if len(vs) < audit.RowsPage {
			return nil
		}

		after = vs[len(vs)-1]
	}
}

// archivedDigests is what the newest line of the archive about each thing
// of a kind keeps, as a check of the rows asks for it; see [trail.Newest].
func archivedDigests(n *trail.Newest) audit.Archived {
	return func(ctx context.Context, kind pdid.Domain) (map[pdid.Id]audit.Recorded, error) {
		vs, err := n.All(ctx, kind)
		if err != nil {
			return nil, err
		}

		out := make(map[pdid.Id]audit.Recorded, len(vs))
		for k, v := range vs {
			out[k] = audit.Recorded{Digest: v.Digest, Fields: v.DigestFields, Line: v.Line()}
		}

		return out, nil
	}
}

// uuids is identifiers as ent's predicates take them.
func uuids(ids []pdid.Id) []uuid.UUID {
	out := make([]uuid.UUID, len(ids))
	for i, v := range ids {
		out[i] = uuid.UUID(v)
	}

	return out
}

// Record puts on the trail rows that were written beneath the servers on
// purpose -- a workspace put back from its export, rows a migration rewrote
// and somebody looked at -- as the act `action` names (payday#108): one line
// of the trail for each, by whoever `ctx` is framed as and filed under the
// row's own tenant, keeping the digest of the row as a Get reads it now and
// nothing of what it holds. A check of the rows then finds each as it is
// now, and the trail says who put it there, when, and by what.
//
// It writes nothing but the trail. `db` is the transaction that wrote the
// rows, or the database. A row of a kind kept off the trail (`trail: {off:
// ...}}`) is passed over; one that is no row at all is an error, since that
// is [RecordErased]'s. A row erased softly is a row. It answers how many it
// recorded.
func Record(ctx context.Context, db *ent.Client, content audit.Contents, action string, ids []pdid.Id) (int, error) {
	return record(ctx, db, content, action, ids, true)
}

// RecordErased puts on the trail rows that were removed beneath the servers
// on purpose -- what a person forgotten took with them, a workspace
// destroyed -- as the act `action` names (payday#115): one line of the trail
// for each, by whoever `ctx` is framed as, keeping a digest that says the row
// went. Without it a check of the rows finds each a thing the trail says is a
// row and is not, which is what a row somebody removed past the servers is.
//
// There is no row to file it under, so it is filed under the tenant `ctx`
// is framed as, as the recorder files an erase that took its row. One that
// is still a row is an error -- that is [Record]'s -- and one of a kind kept
// off the trail is passed over. It answers how many it recorded.
func RecordErased(ctx context.Context, db *ent.Client, content audit.Contents, action string, ids []pdid.Id) (int, error) {
	return record(ctx, db, content, action, ids, false)
}

// record is [Record] when `there`, and [RecordErased] when not.
func record(ctx context.Context, db *ent.Client, content audit.Contents, action string, ids []pdid.Id, there bool) (int, error) {
	if action == "" {
		return 0, errors.New("an act on the trail is named")
	}

	s, err := bare.NewServer(db)
	if err != nil {
		return 0, err
	}

	ids = slices.Clone(ids)
	slices.SortFunc(ids, func(a, b pdid.Id) int { return uuid.UUID(a).Compare(uuid.UUID(b)) })
	ids = slices.Compact(ids)

	byKind := map[pdid.Domain][]pdid.Id{}
	for _, v := range ids {
		byKind[v.Domain()] = append(byKind[v.Domain()], v)
	}

	n := 0
	for _, d := range slices.Sorted(maps.Keys(byKind)) {
		for page := range slices.Chunk(byKind[d], audit.RowsPage) {
			var rows []audit.Live
			switch d {
			case BillingAccountDomain:
				rows, err = rowsBillingAccount(ctx, db, entBillingAccount.IdIn(uuids(page)...))
			case DepartureDomain:
				rows, err = rowsDeparture(ctx, db, entDeparture.IdIn(uuids(page)...))
			case GrantDomain:
				rows, err = rowsGrant(ctx, db, entGrant.IdIn(uuids(page)...))
			case HolderDomain:
				rows, err = rowsHolder(ctx, db, entHolder.IdIn(uuids(page)...))
			case LinkDomain:
				rows, err = rowsLink(ctx, db, entLink.IdIn(uuids(page)...))
			case MeterDomain:
				rows, err = rowsMeter(ctx, db, entMeter.IdIn(uuids(page)...))
			case OfferDomain:
				rows, err = rowsOffer(ctx, db, entOffer.IdIn(uuids(page)...))
			case OperatorDomain:
				rows, err = rowsOperator(ctx, db, entOperator.IdIn(uuids(page)...))
			case PeriodDomain:
				rows, err = rowsPeriod(ctx, db, entPeriod.IdIn(uuids(page)...))
			case PointDomain:
				rows, err = rowsPoint(ctx, db, entPoint.IdIn(uuids(page)...))
			case PriceDomain:
				rows, err = rowsPrice(ctx, db, entPrice.IdIn(uuids(page)...))
			case ReadingDomain:
				rows, err = rowsReading(ctx, db, entReading.IdIn(uuids(page)...))
			case SeriesDomain:
				rows, err = rowsSeries(ctx, db, entSeries.IdIn(uuids(page)...))
			case ServiceKeyDomain:
				rows, err = rowsServiceKey(ctx, db, entServiceKey.IdIn(uuids(page)...))
			case StatementDomain:
				rows, err = rowsStatement(ctx, db, entStatement.IdIn(uuids(page)...))
			case TenantDomain:
				rows, err = rowsTenant(ctx, db, entTenant.IdIn(uuids(page)...))
			case WorkspaceDomain:
				rows, err = rowsWorkspace(ctx, db, entWorkspace.IdIn(uuids(page)...))
			default:
				// Kept off the trail, so no act on it is recorded.
				continue
			}
			if err != nil {
				return n, err
			}

			if there && len(rows) != len(page) {
				return n, fmt.Errorf("%s is no row", unread(page, rows))
			}
			if !there && len(rows) > 0 {
				return n, fmt.Errorf("%s is still a row", rows[0].Object)
			}
			if !there {
				rows = make([]audit.Live, len(page))
				for i, id := range page {
					rows[i] = audit.Live{Object: id}
				}
			}

			if err := recordRows(ctx, db, s, action, content, rows); err != nil {
				return n, err
			}
			n += len(rows)
		}
	}

	return n, nil
}

// unread is the first of `ids` that `rows` does not have.
func unread(ids []pdid.Id, rows []audit.Live) pdid.Id {
	for _, id := range ids {
		if !slices.ContainsFunc(rows, func(v audit.Live) bool { return v.Object == id }) {
			return id
		}
	}

	return pdid.Nil
}

// recordRows writes the line [Record] says for each of `rows`, and the one
// [RecordErased] says for each of them that has no row.
func recordRows(ctx context.Context, db *ent.Client, s bare.Server, action string, content audit.Contents, rows []audit.Live) error {
	qs := make([]*ent.AuditCreate, 0, len(rows))
	// And the seal of each row of a sealed kind, as its write would leave it:
	// written over the one there is, or removed with the row.
	seals := make([]*rowSeal, 0, len(rows))
	for _, v := range rows {
		w, err := audit.Of(ctx, action, v.Object, nil)
		if err != nil {
			return err
		}

		at := line(s, action)
		digest, covered, sealing, err := digested(content.Digest, v.Object, v.Row, at)
		if err != nil {
			return fmt.Errorf("the trail of %s: %w", action, err)
		}

		// Filed where the recorder files a write of it: under its tenant, or
		// the actor's when it is behind no wall or is no row.
		tenant, _, err := subject(ctx, s, v.Object, v.Row, false)
		if err != nil {
			return err
		}
		if tenant == uuid.Nil() {
			tenant = uuid.UUID(w.Tenant)
		}
		seals = append(seals, sealing.in(tenant))
		domain := uint32(v.Object.Domain())

		q := db.Audit.Create().
			SetId(uuid.UUID(at.Id)).
			SetTenantId(tenant).
			SetActorTenantId(uuid.UUID(w.Tenant)).
			SetActorId(uuid.UUID(w.Actor)).
			SetTraceId(notNull(w.Trace)).
			SetAction(action).
			SetObjectId(uuid.UUID(v.Object)).
			SetDomain(domain).
			SetPatch([]byte{}).
			SetValue([]byte{}).
			SetFields([]uint32{}).
			SetDigest(digest).
			SetDigestFields(covered).
			SetDateCreated(at.Created)
		if !w.Counterpart.IsZero() {
			q.SetCounterpartTenantId(uuid.UUID(w.Counterpart))
		}
		qs = append(qs, q)
	}

	for vs := range slices.Chunk(qs, keptTrailRows) {
		if err := db.Audit.CreateBulk(vs...).Exec(ctx); err != nil {
			return fmt.Errorf("write the trail: %w", err)
		}
	}

	return keepSeals(ctx, db, seals...)
}

func (s trailStore) Carry(ctx context.Context, digest *audit.Digest, d pdid.Domain, vs []trail.Carried) (int, error) {
	n := 0
	for page := range slices.Chunk(vs, audit.RowsPage) {
		ids := make([]pdid.Id, len(page))
		for i, v := range page {
			ids[i] = v.Object
		}

		var rows []audit.Live
		var err error
		switch d {
		case BillingAccountDomain:
			rows, err = rowsBillingAccount(ctx, s.db, entBillingAccount.IdIn(uuids(ids)...))
		case DepartureDomain:
			rows, err = rowsDeparture(ctx, s.db, entDeparture.IdIn(uuids(ids)...))
		case GrantDomain:
			rows, err = rowsGrant(ctx, s.db, entGrant.IdIn(uuids(ids)...))
		case HolderDomain:
			rows, err = rowsHolder(ctx, s.db, entHolder.IdIn(uuids(ids)...))
		case LinkDomain:
			rows, err = rowsLink(ctx, s.db, entLink.IdIn(uuids(ids)...))
		case MeterDomain:
			rows, err = rowsMeter(ctx, s.db, entMeter.IdIn(uuids(ids)...))
		case OfferDomain:
			rows, err = rowsOffer(ctx, s.db, entOffer.IdIn(uuids(ids)...))
		case OperatorDomain:
			rows, err = rowsOperator(ctx, s.db, entOperator.IdIn(uuids(ids)...))
		case PeriodDomain:
			rows, err = rowsPeriod(ctx, s.db, entPeriod.IdIn(uuids(ids)...))
		case PointDomain:
			rows, err = rowsPoint(ctx, s.db, entPoint.IdIn(uuids(ids)...))
		case PriceDomain:
			rows, err = rowsPrice(ctx, s.db, entPrice.IdIn(uuids(ids)...))
		case ReadingDomain:
			rows, err = rowsReading(ctx, s.db, entReading.IdIn(uuids(ids)...))
		case SeriesDomain:
			rows, err = rowsSeries(ctx, s.db, entSeries.IdIn(uuids(ids)...))
		case ServiceKeyDomain:
			rows, err = rowsServiceKey(ctx, s.db, entServiceKey.IdIn(uuids(ids)...))
		case StatementDomain:
			rows, err = rowsStatement(ctx, s.db, entStatement.IdIn(uuids(ids)...))
		case TenantDomain:
			rows, err = rowsTenant(ctx, s.db, entTenant.IdIn(uuids(ids)...))
		case WorkspaceDomain:
			rows, err = rowsWorkspace(ctx, s.db, entWorkspace.IdIn(uuids(ids)...))
		default:
			// A kind no check reads, so there is nothing to carry forward to.
			return n, nil
		}
		if err != nil {
			return n, err
		}

		there := map[pdid.Id]bool{}
		for _, v := range rows {
			there[v.Object] = true
		}

		about, err := s.db.Audit.Query().
			Where(entAudit.ObjectIdIn(uuids(ids)...)).
			Select(entAudit.FieldObjectId).
			All(ctx)
		if err != nil {
			return n, err
		}
		for _, v := range about {
			delete(there, pdid.Id(v.ObjectId))
		}

		srv, err := bare.NewServer(s.db)
		if err != nil {
			return n, err
		}
		qs := []*ent.AuditCreate{}
		// The seals of the rows carried for, which go with their lines.
		rebound := map[pdid.Id]audit.Line{}
		tenants := map[pdid.Id]uuid.UUID{}
		for _, v := range page {
			if !there[v.Object] {
				continue
			}

			at := line(srv, trail.CarriedAction)
			if isSealed(v.Object) {
				rebound[v.Object] = at
				tenants[v.Object] = v.Tenant.Uuid()
			}
			sum, err := digest.Carry(v.Sum, v.Object, at)
			if err != nil {
				return n, fmt.Errorf("carry %s forward: %w", v.Object, err)
			}

			domain := uint32(d)
			qs = append(qs, s.db.Audit.Create().
				SetId(uuid.UUID(at.Id)).
				SetTenantId(v.Tenant.Uuid()).
				SetActorTenantId(uuid.Nil()).
				SetActorId(uuid.Nil()).
				SetTraceId([]byte{}).
				SetAction(at.Action).
				SetObjectId(v.Object.Uuid()).
				SetDomain(domain).
				SetPatch([]byte{}).
				SetValue([]byte{}).
				SetFields([]uint32{}).
				SetDigest(sum).
				SetDigestFields(v.DigestFields).
				SetDateCreated(at.Created))
		}
		for vs := range slices.Chunk(qs, keptTrailRows) {
			if err := s.db.Audit.CreateBulk(vs...).Exec(ctx); err != nil {
				return n, fmt.Errorf("write the trail: %w", err)
			}
			n += len(vs)
		}
		if err := carrySeals(ctx, s.db, digest, rebound, tenants); err != nil {
			return n, err
		}
	}

	return n, nil
}

